// internal-task sealed custody, branches the other sealed tests do not reach (generated by the /ship test coverage audit,
// generation pass 2). On the synthetic set of tests/sealed-fixture.ts with an opening budget of one: open removes its
// output directory when a check after decryption fails, collectSecrets gathers the sealed strings the leak scan looks for,
// export publishes per-cell and per-task results under opaque ids once the reserve opening is spent (and --mode embargo
// still holds them back), a rerun finishes an export whose write into sealed-results/ failed after the custody push and
// refuses one that is complete or cannot be finished, and receipts-manifest.ts lists each sealed export and flags a receipt
// export.json does not name. A rerun still finishes an export whose run has two identical exported lines, a custody push
// reported rejected after it landed is logged once, and cleanup.ts refuses an export.json without README.md or under a
// directory it removes, and removes a sealed shard's root copy named by sealed-root-copy.path. Export makes a stale
// comparisons.json again before it decides, and refuses another recipient in sealed/recipient.txt, a receipt the access log
// did not admit and a set with a "released" line (before the push and inside it).
// A separate block covers summarize-run.ts on a plaintext run whose task tree is missing: family "unknown" with a WARN line
// and families_unresolved (HE-TASK-005; only a sealed run refuses). Every key is generated
// here and thrown away; assertion labels name files and counts, never a sealed string.
import { afterAll, describe, expect, test } from 'bun:test';
import { spawnSync } from 'node:child_process';
import { chmodSync, existsSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, renameSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { sha256, verifySealedRoot } from '../runner/heldout/sealed.ts';
import type { TrialRecord } from '../runner/contracts.ts';
import { openRun } from '../scripts/sealed/open.ts';
import { readAccessLog } from '../scripts/sealed/custody.ts';
import { generateX25519Identity, identityToRecipient } from 'age-encryption';
import { collectSecrets, exportRun, rawEntries, type ExportOptions } from '../scripts/sealed/export.ts';
import { cleanup } from '../scripts/sealed/cleanup.ts';
import { buildManifest } from '../scripts/receipts-manifest.ts';
import { candidate, cloneCustody, co, commitPush, git, makeFixture, manifestPath, register, ROOT, SECRETS, SET, type Fixture, type RunSpec } from './sealed-fixture.ts';

const tmps: string[] = [];
afterAll(() => { for (const d of tmps) rmSync(d, { recursive: true, force: true }); });

const TASKS = ['sx-01-vault-ask', 'sx-02-dm-guard'];
const SEALED = [...Object.values(SECRETS), ...TASKS];
const A: RunSpec = { runId: 'syn-full', dir: '2026-11-20-syn-full', label: 'confirmatory', candidate: candidate('full') };
const B: RunSpec = { runId: 'syn-dev', dir: '2026-11-21-syn-dev', label: 'dev', reason: 'synthetic dev opening after the reserve is spent', candidate: candidate('dev') };
const preregOf = (r: RunSpec) => `docs/benchmarks/${r.dir}/prereg.json`;
const sealedResultsOf = (f: Fixture, r: RunSpec) => join(f.repo, 'docs', 'benchmarks', r.dir, 'sealed-results');

describe('sealed custody with the reserve opening spent', () => {
  let f: Fixture;
  const rootA = () => join(f.work, 'root-full');

  // Value: protects=open removes --out when a check after decryption fails, so no sealed plaintext is left on disk, and the
  //   opening stays logged and resumes once fixed; fails_when=the catch after decryption stops removing --out, or the digest
  //   check is skipped; why_new=open tests cover admission refusals and a failed push only; seam=none;
  //   no_claim=the slice and corpus digest checks (same catch, not driven here); fixture repo and custody remote are local
  test('open removes its output directory when the decrypted tree does not match the commitment on main, then resumes once main is fixed', async () => {
    f = await makeFixture(1);
    tmps.push(f.tmp);
    register(f, A);
    const p = manifestPath(f);
    const m = JSON.parse(readFileSync(p, 'utf8')) as { tree_sha256: string };
    const committed = m.tree_sha256;
    writeFileSync(p, JSON.stringify({ ...m, tree_sha256: 'f'.repeat(64) }, null, 2) + '\n');
    commitPush(f, 'change the committed tree digest');

    const err = await openRun({ repo: f.repo, prereg: preregOf(A), ...co(f), out: rootA(), log: () => undefined }).then(() => null, (e: Error) => e);
    expect(err?.message ?? 'no error').toMatch(/HE-SEALED-006 the decrypted bundle's tree_sha256 is [0-9a-f]{12}, the public commitment is f{12}$/);
    expect(existsSync(rootA())).toBe(false);
    expect(readdirSync(f.work)).toEqual([]);
    // the access-log line was pushed before decryption and stays: the opening is counted
    expect(readAccessLog(cloneCustody(f, 'check-g7')).map((e) => [e.event, e.run_id])).toEqual([['sealed', '*'], ['opened', A.runId]]);

    writeFileSync(p, JSON.stringify({ ...m, tree_sha256: committed }, null, 2) + '\n');
    commitPush(f, 'restore the committed tree digest');
    const r = await openRun({ repo: f.repo, prereg: preregOf(A), ...co(f), out: rootA(), log: () => undefined });
    expect(r.resumed).toBe(true);
    expect(verifySealedRoot(rootA(), r.receipt, f.repo)).toEqual([]);
  }, 120_000);

  // Value: protects=collectSecrets returns the task ids, task strings and corpus lines of an opened root and drops text that
  //   is public; fails_when=the regex, length floor or public-text filter empties or skews the set, so the leak scan passes
  //   vacuously; why_new=leakScan is unit-tested with a hand-made secret, nothing tests collection; seam=none;
  //   no_claim=secrets shorter than the eight-character floor; raw summary strings (raw dir is empty here)
  test('collectSecrets gathers the task ids, a hidden fact and a corpus line from the opened root, and leaves public world text out', () => {
    const raw = mkdtempSync(join(tmpdir(), 'he-sealed-raw-'));
    tmps.push(raw);
    const worldText = readFileSync(join(f.repo, 'world', 'seed', 'world.json'), 'utf8');
    const secrets = collectSecrets({ root: rootA(), set: SET, raw, publicTexts: [worldText] });
    const kindOf = (s: string) => secrets.find((x) => x.text === s)?.kind ?? 'absent';
    expect(TASKS.map(kindOf)).toEqual(['task id', 'task id']);
    expect(kindOf(SECRETS.hiddenFact)).toBe('task string');
    expect(kindOf(SECRETS.corpusLine)).toBe('corpus line');
    // a public message the slice carries unchanged is public text, so it is not a secret
    const pub = JSON.parse(worldText) as { messages: Array<{ text: string; split?: string }> };
    const publicMessage = pub.messages.find((x) => x.split !== 'heldout' && x.text.trim().length >= 8)!.text.trim();
    const slice = JSON.parse(readFileSync(join(rootA(), 'world', 'slice.json'), 'utf8')) as { messages: Array<{ text: string }> };
    expect(slice.messages.some((x) => x.text.trim() === publicMessage)).toBe(true);
    expect(kindOf(publicMessage)).toBe('absent');
    // a sealed line that also appears in a public text leaves the set
    expect(collectSecrets({ root: rootA(), set: SET, raw, publicTexts: [worldText, SECRETS.corpusLine] }).some((x) => x.text === SECRETS.corpusLine)).toBe(false);
  });

  // Value: protects=once the reserve is spent the export carries per-cell aggregates and per-task counts under T- opaque ids
  //   with no sealed string, and --mode embargo still holds them back; fails_when=full mode names a raw task id, drops
  //   per_task or cells, or --mode embargo stops forcing embargo; why_new=sealed-e2e.test.ts runs embargo mode only;
  //   seam=none; no_claim=the per-cell numbers (summarize-run's own tests); scripted oracle trials, fake gh, local custody remote
  test('export after the reserve is spent publishes per-cell and per-task results under opaque ids; --mode embargo still embargoes', async () => {
    register(f, B);
    const rootB = (await openRun({ repo: f.repo, prereg: preregOf(B), ...co(f), out: join(f.work, 'root-dev'), log: () => undefined })).root;
    const bun = (args: string[]) => spawnSync(process.execPath, args, { cwd: f.repo, encoding: 'utf8', env: { PATH: process.env.PATH, HOME: process.env.HOME } });
    const runOne = (r: RunSpec, root: string) => {
      const results = join(f.work, 'results', r.runId);
      const flags = ['--sealed-root', root, '--opening-receipt', join(root, 'opening-receipt.json')];
      const plan = bun([join(ROOT, 'runner', 'run.ts'), 'plan', '--prereg', preregOf(r), '--out', results, ...flags]);
      expect(`${r.runId} plan exit ${plan.status}`).toBe(`${r.runId} plan exit 0`);
      const exec = bun([join(ROOT, 'runner', 'run.ts'), 'run', '--manifest', join(results, 'manifest.json'), '--harness-mode', 'scripted', ...flags]);
      expect(`${r.runId} run exit ${exec.status}`).toBe(`${r.runId} run exit 0`);
      return results;
    };
    const resultsA = runOne(A, rootA()), resultsB = runOne(B, rootB);

    // an --out other than the run's sealed-results directory is refused before anything is pushed
    const wrongOut = await exportRun({ repo: f.repo, results: resultsA, sealedRoot: rootA(), receipt: join(rootA(), 'opening-receipt.json'), custody: cloneCustody(f, 'custody-export-wrong'), gh: f.gh, out: join(f.repo, 'docs', 'elsewhere'), log: () => undefined }).then(() => null, (e: Error) => e.message);
    expect(wrongOut).toMatch(/HE-SEALED-007 --out .* is not docs\/benchmarks\/.*\/sealed-results, the run's sealed-results directory/);
    expect(readAccessLog(cloneCustody(f, 'check-wrong-out')).filter((e) => e.event === 'exported').length).toBe(0);
    const a = await exportRun({ repo: f.repo, results: resultsA, sealedRoot: rootA(), receipt: join(rootA(), 'opening-receipt.json'), custody: cloneCustody(f, 'custody-export-a'), gh: f.gh, log: () => undefined });
    const ea = a.export as { mode: string; budget: Record<string, unknown>; cells?: Record<string, { n: number }>; per_task?: Array<{ task: string; cells: Record<string, { passes: number; trials: number }> }>; decisions: Array<Record<string, unknown>> };
    expect(ea.mode).toBe('full');
    expect(ea.budget).toMatchObject({ opening_budget: 1, confirmatory_opened: 1, reserve_unused: false });
    expect(Object.keys(ea.cells ?? {}).sort()).toEqual(['base', 'cand']);
    expect([ea.cells!.base!.n, ea.cells!.cand!.n]).toEqual([4, 4]);
    expect(ea.per_task?.length).toBe(2);
    for (const row of ea.per_task!) {
      expect(/^T-[0-9a-f]{10}$/.test(row.task)).toBe(true);
      expect(Object.keys(row.cells).sort()).toEqual(['base', 'cand']);
      expect([row.cells.base!.trials, row.cells.cand!.trials]).toEqual([2, 2]);
    }
    expect(new Set(ea.per_task!.map((r) => r.task)).size).toBe(2);
    expect(ea.decisions.map((d) => ['claim', 'decision', 'holm_p', 'estimate'].every((k) => k in d))).toEqual([true, true]);
    for (const n of readdirSync(a.out)) {
      const text = readFileSync(join(a.out, n), 'utf8');
      expect(`${n}: ${SEALED.filter((s) => text.includes(s)).length} sealed string(s)`).toBe(`${n}: 0 sealed string(s)`);
    }

    // B's write into sealed-results/ fails after the custody push (README.md is a directory there): custody holds the bundle
    // and the exported line, the three public files are staged in the raw results, and a rerun finishes the export from them
    const outB = sealedResultsOf(f, B);
    mkdirSync(join(outB, 'README.md'), { recursive: true });
    const argsB = { repo: f.repo, results: resultsB, sealedRoot: rootB, receipt: join(rootB, 'opening-receipt.json'), gh: f.gh, mode: 'embargo' as const, log: () => undefined };
    const crashed = await exportRun({ ...argsB, custody: cloneCustody(f, 'custody-export-b') }).then(() => 'no error', (e: Error) => e.constructor.name);
    expect(crashed).not.toBe('no error');
    const crashLog = readAccessLog(cloneCustody(f, 'check-crash')).filter((e) => e.event === 'exported');
    expect(crashLog.map((e) => e.run_id)).toEqual([A.runId, B.runId]);
    // the staged files sit under the digest of the bundle they name
    const stagedB = join(resultsB, 'export-pending', String(crashLog[1]!.results_bundle_sha256));
    expect(readdirSync(stagedB).sort()).toEqual(['README.md', 'export.json', 'opening-receipt.json']);
    expect([statSync(stagedB).mode & 0o777, statSync(join(resultsB, 'export-pending')).mode & 0o777]).toEqual([0o700, 0o700]);
    expect(rawEntries(resultsB).filter((e) => e.path.startsWith('export-pending/')).length).toBe(0);
    rmSync(join(outB, 'README.md'), { recursive: true });
    const b = await exportRun({ ...argsB, custody: cloneCustody(f, 'custody-export-b2') });
    expect(b.out).toBe(outB);
    for (const n of ['export.json', 'opening-receipt.json', 'README.md']) expect(`${n} identical to the staged file: ${readFileSync(join(outB, n)).equals(readFileSync(join(stagedB, n)))}`).toBe(`${n} identical to the staged file: true`);
    const expB = JSON.parse(readFileSync(join(outB, 'export.json'), 'utf8')) as { sealed_results: { results_bundle_sha256: string } };
    expect(readAccessLog(cloneCustody(f, 'check-finished')).find((e) => e.event === 'exported' && e.run_id === B.runId)?.results_bundle_sha256).toBe(expB.sealed_results.results_bundle_sha256);
    expect(b.export.mode).toBe('embargo');
    expect((b.export.budget as { reserve_unused: boolean }).reserve_unused).toBe(false);
    expect(b.export.cells).toBeUndefined();
    expect(b.export.per_task).toBeUndefined();
    expect(readAccessLog(cloneCustody(f, 'check-g8')).map((e) => e.event)).toEqual(['sealed', 'opened', 'resumed', 'opened', 'exported', 'exported']);
    // a second export of the same run is refused as complete and leaves the published files as they were
    const published = readFileSync(join(a.out, 'export.json'), 'utf8');
    let n = 0;
    const exportA = () => exportRun({ repo: f.repo, results: resultsA, sealedRoot: rootA(), receipt: join(rootA(), 'opening-receipt.json'), custody: cloneCustody(f, `custody-export-again-${++n}`), gh: f.gh, log: () => undefined });
    const again = await exportA().then(() => null, (e: Error) => e.message);
    expect(again).toMatch(/^HE-SEALED-007 run \S+ is already exported and its public export is complete: docs\/benchmarks\/\S+\/sealed-results\/ holds the three files, and its export\.json names \S+\/results\/\S+\.tar\.age \([0-9a-f]{12}\), which refs\/heads\/custody holds with its exported line; a sealed results bundle is never replaced\. Nothing was written$/);
    expect(readFileSync(join(a.out, 'export.json'), 'utf8')).toBe(published);
    // the published files lost after the push (an ephemeral machine, a crash): a rerun writes them again, byte for byte
    rmSync(a.out, { recursive: true });
    expect((await exportA()).out).toBe(a.out);
    expect(readFileSync(join(a.out, 'export.json'), 'utf8')).toBe(published);
    // a truncated export.json (a crash in the middle of the copy) is repaired from the staged files too
    writeFileSync(join(a.out, 'export.json'), published.slice(0, 40));
    expect((await exportA()).out).toBe(a.out);
    expect(readFileSync(join(a.out, 'export.json'), 'utf8')).toBe(published);
    // with neither the published nor the staged files the export cannot be finished, and the refusal names what is missing
    const parkedPending = join(f.tmp, 'parked-pending');
    renameSync(join(resultsA, 'export-pending'), parkedPending);
    rmSync(a.out, { recursive: true });
    const unfinished = await exportA().then(() => null, (e: Error) => e.message);
    expect(unfinished).toMatch(/^HE-SEALED-007 run \S+ is already exported and its public export cannot be finished: refs\/heads\/custody holds \S+ \([0-9a-f]{12}\) with its exported line, but docs\/benchmarks\/\S+\/sealed-results\/export\.json is missing and the staged \S+\/export-pending\/[0-9a-f]{64}\/export\.json is missing\. A sealed results bundle is never replaced, so a new export cannot stand in for it; nothing was written \(report this to the Captain\)$/);
    expect(existsSync(a.out)).toBe(false);
    renameSync(parkedPending, join(resultsA, 'export-pending'));
    await exportA();
    expect(readFileSync(join(a.out, 'export.json'), 'utf8')).toBe(published);
    expect(readAccessLog(cloneCustody(f, 'check-reruns')).filter((e) => e.event === 'exported').length).toBe(2);
  }, 120_000);

  // Value: protects=each sealed-results dir yields a sealed_runs row bound to its receipt, a receipt export.json does not name
  //   is a problem, and no sealed-results dir means no sealed_runs key; fails_when=the receipt check is dropped, or the key
  //   appears in a repo with no sealed runs; why_new=receipts-manifest.test.ts has no sealed-results fixture; seam=none;
  //   no_claim=the numbers inside export.json; --check against a committed manifest
  test('receipts-manifest lists each sealed export with its digests, flags a receipt export.json does not name, and adds no key without sealed runs', () => {
    const dirA = sealedResultsOf(f, A), dirB = sealedResultsOf(f, B);
    const expA = JSON.parse(readFileSync(join(dirA, 'export.json'), 'utf8')) as { opening: number | null; sealed_results: { results_bundle_sha256: string; raw_tree_sha256: string; trials_jsonl_sha256: string } };
    const expB = JSON.parse(readFileSync(join(dirB, 'export.json'), 'utf8')) as { opening: number | null };
    const rows = buildManifest(f.repo, '2026-11-22T00:00:00.000Z').sealed_runs ?? [];
    expect(rows.map((r) => [r.directory, r.run_id, r.set, r.label, r.mode])).toEqual([
      [`docs/benchmarks/${A.dir}`, A.runId, SET, 'confirmatory', 'full'],
      [`docs/benchmarks/${B.dir}`, B.runId, SET, 'dev', 'embargo'],
    ]);
    expect(rows.map((r) => r.problems)).toEqual([[], []]);
    expect(rows.map((r) => r.opening)).toEqual([1, expB.opening]);
    expect(expA.opening).toBe(1);
    expect(rows[0]!.export_sha256).toBe(sha256(readFileSync(join(dirA, 'export.json'))));
    expect(rows[0]!.receipt_sha256).toBe(sha256(readFileSync(join(dirA, 'opening-receipt.json'))));
    expect([rows[0]!.results_bundle_sha256, rows[0]!.raw_tree_sha256, rows[0]!.trials_jsonl_sha256]).toEqual([expA.sealed_results.results_bundle_sha256, expA.sealed_results.raw_tree_sha256, expA.sealed_results.trials_jsonl_sha256]);
    expect(rows[0]!.decisions.map((d) => d.claim)).toEqual(['C1', 'C2']);

    // B's receipt published beside A's export
    const receiptA = readFileSync(join(dirA, 'opening-receipt.json'));
    writeFileSync(join(dirA, 'opening-receipt.json'), readFileSync(join(dirB, 'opening-receipt.json')));
    const swapped = buildManifest(f.repo).sealed_runs!;
    expect(swapped[0]!.problems).toEqual(['opening-receipt.json is not the receipt export.json names (receipt_sha256 differs)', `the receipt names run ${B.runId} on set ${SET}, export.json names ${A.runId} on ${SET}`]);
    expect(swapped[1]!.problems).toEqual([]);
    writeFileSync(join(dirA, 'opening-receipt.json'), receiptA);

    const parked = join(f.tmp, 'parked');
    mkdirSync(parked);
    renameSync(dirA, join(parked, 'a'));
    renameSync(dirB, join(parked, 'b'));
    expect('sealed_runs' in buildManifest(f.repo)).toBe(false);
    renameSync(join(parked, 'a'), dirA);
    renameSync(join(parked, 'b'), dirB);
  }, 60_000);

  // Value: protects=a rerun still finishes an export whose run has two identical exported lines, and a custody push that
  //   landed but was reported rejected is not logged a second time; fails_when=the recovery path again demands exactly one
  //   exported line, or decide appends a line for a bundle the log already names; why_new=the rerun tests above have one
  //   line per run and a push that either lands or fails; seam=a git update hook that moves the ref and then declines;
  //   no_claim=a lost push on a real network; fixture repo and custody remote are local
  test('export recovery accepts several exported lines naming one bundle, and a push reported rejected after it landed is logged once', async () => {
    const resultsA = join(f.work, 'results', A.runId), outA = sealedResultsOf(f, A);
    const published = readFileSync(join(outA, 'export.json'), 'utf8');
    const dup = cloneCustody(f, 'custody-dup-line');
    const line = readFileSync(join(dup, 'access-log.jsonl'), 'utf8').split('\n').find((l) => l.includes('"exported"') && l.includes(`"${A.runId}"`))!;
    writeFileSync(join(dup, 'access-log.jsonl'), readFileSync(join(dup, 'access-log.jsonl'), 'utf8') + line + '\n');
    git(dup, 'commit', '-q', '-am', 'a second identical exported line');
    git(dup, 'push', '-q', 'origin', 'HEAD:refs/heads/custody');
    expect(readAccessLog(cloneCustody(f, 'check-dup')).filter((e) => e.event === 'exported' && e.run_id === A.runId).length).toBe(2);
    rmSync(outA, { recursive: true });
    const again = await exportRun({ repo: f.repo, results: resultsA, sealedRoot: rootA(), receipt: join(rootA(), 'opening-receipt.json'), custody: cloneCustody(f, 'custody-export-dup'), gh: f.gh, log: () => undefined });
    expect(again.out).toBe(outA);
    expect(readFileSync(join(outA, 'export.json'), 'utf8')).toBe(published);
    expect(readdirSync(outA).sort()).toEqual(['README.md', 'export.json', 'opening-receipt.json']);

    const C: RunSpec = { runId: 'syn-dev-2', dir: '2026-11-23-syn-dev-2', label: 'dev', reason: 'synthetic second dev opening', candidate: candidate('dev-2') };
    register(f, C);
    const rootC = (await openRun({ repo: f.repo, prereg: preregOf(C), ...co(f), out: join(f.work, 'root-dev-2'), log: () => undefined })).root;
    const resultsC = join(f.work, 'results', C.runId);
    const flags = ['--sealed-root', rootC, '--opening-receipt', join(rootC, 'opening-receipt.json')];
    const bun = (args: string[]) => spawnSync(process.execPath, args, { cwd: f.repo, encoding: 'utf8', env: { PATH: process.env.PATH, HOME: process.env.HOME } });
    expect(bun([join(ROOT, 'runner', 'run.ts'), 'plan', '--prereg', preregOf(C), '--out', resultsC, ...flags]).status).toBe(0);
    expect(bun([join(ROOT, 'runner', 'run.ts'), 'run', '--manifest', join(resultsC, 'manifest.json'), '--harness-mode', 'scripted', ...flags]).status).toBe(0);
    const marker = join(f.tmp, 'custody-push-landed-once'), hook = join(f.bare, 'hooks', 'update');
    mkdirSync(join(f.bare, 'hooks'), { recursive: true });
    writeFileSync(hook, `#!/usr/bin/env bash\n[ "$1" = refs/heads/custody ] && [ ! -e '${marker}' ] || exit 0\ntouch '${marker}'\ngit update-ref "$1" "$3" "$2" || exit 1\necho "custody push declined by the test hook after it landed" >&2\nexit 1\n`);
    chmodSync(hook, 0o755);
    try {
      const c = await exportRun({ repo: f.repo, results: resultsC, sealedRoot: rootC, receipt: join(rootC, 'opening-receipt.json'), custody: cloneCustody(f, 'custody-export-c'), gh: f.gh, log: () => undefined });
      expect(existsSync(marker)).toBe(true);
      const lines = readAccessLog(cloneCustody(f, 'check-landed')).filter((e) => e.event === 'exported' && e.run_id === C.runId);
      expect(lines.map((e) => e.results_bundle_sha256)).toEqual([(c.export.sealed_results as { results_bundle_sha256: string }).results_bundle_sha256]);
      expect(readdirSync(c.out).sort()).toEqual(['README.md', 'export.json', 'opening-receipt.json']);
    } finally { rmSync(hook, { force: true }); }
  }, 120_000);

  // Value: protects=cleanup removes nothing unless --export is the run's complete sealed-results copy in the checkout, and
  //   removes a sealed shard's private root copy a SIGKILL left behind; fails_when=cleanup trusts an export.json without
  //   README.md or with an export under a directory it removes, or ignores sealed-root-copy.path; why_new=sealed-e2e covers
  //   the custody proof and the results binding only; seam=none; no_claim=a real killed shard (run-shard.sh's own tests)
  test('cleanup refuses a partial or misplaced export and removes a sealed shard copy a killed shard left', () => {
    const resultsA = join(f.work, 'results', A.runId), outA = sealedResultsOf(f, A);
    const custody = cloneCustody(f, 'custody-cleanup');
    const run = (exportJson: string, results = [resultsA]) => cleanup({ repo: f.repo, exportJson, sealedRoot: rootA(), results, custody, log: () => undefined });
    const refused = (exportJson: string, results?: string[]) => { try { run(exportJson, results); return 'no refusal'; } catch (e) { return (e as Error).message; } };
    renameSync(join(outA, 'README.md'), join(f.tmp, 'parked-readme'));
    expect(refused(join(outA, 'export.json'))).toMatch(/^HE-SEALED-014 \S+\/sealed-results has export\.json but no README\.md, so the public export is not a complete copy; .*nothing was removed$/);
    renameSync(join(f.tmp, 'parked-readme'), join(outA, 'README.md'));
    const copyTo = (dir: string) => { mkdirSync(dir, { recursive: true }); for (const n of readdirSync(outA)) writeFileSync(join(dir, n), readFileSync(join(outA, n))); return join(dir, 'export.json'); };
    expect(refused(copyTo(join(resultsA, 'export-copy')))).toMatch(/^HE-SEALED-014 --export \S+\/export-copy\/export\.json is inside \S+, which cleanup removes; .*nothing was removed$/);
    rmSync(join(resultsA, 'export-copy'), { recursive: true });
    expect(refused(copyTo(join(f.tmp, 'elsewhere-export')))).toMatch(/^HE-SEALED-014 --export \S+ is not the sealed-results\/export\.json beside the preregistration of syn-full .*nothing was removed$/);
    expect([existsSync(rootA()), existsSync(join(resultsA, 'trials.jsonl'))]).toEqual([true, true]);

    const shardCopy = join(f.tmp, 'harness-eval-sealed-shard.Ab12Cd34'), decoy = join(f.tmp, 'not-a-shard-copy'), otherRun = join(f.tmp, 'harness-eval-sealed-shard.Other000');
    for (const [d, runId] of [[shardCopy, A.runId], [decoy, A.runId], [otherRun, B.runId]] as const) { mkdirSync(join(d, 'root'), { recursive: true }); writeFileSync(join(d, 'root', 'opening-receipt.json'), JSON.stringify({ run_id: runId })); }
    writeFileSync(join(resultsA, 'sealed-root-copy.path'), `${join(f.tmp, 'harness-eval-sealed-shard.gone0000')}\n/home/ubuntu/vm-only/harness-eval-sealed-shard.Vm000000\n`);
    mkdirSync(join(resultsA, 'shard-2'));
    writeFileSync(join(resultsA, 'shard-2', 'sealed-root-copy.path'), `${join(f.tmp, 'harness-eval-sealed-shard.gone1111')}\n${shardCopy}\n`);
    mkdirSync(join(resultsA, 'shard-3'));
    const partial = join(f.tmp, 'harness-eval-sealed-shard.Part0000'), unbound = join(f.tmp, 'harness-eval-sealed-shard.Unbd0000');
    mkdirSync(join(partial, 'root', 'tasks'), { recursive: true }); writeFileSync(join(partial, 'opening-receipt.json'), JSON.stringify({ run_id: A.runId }));
    mkdirSync(join(unbound, 'root', 'tasks'), { recursive: true });
    const noId = join(f.tmp, 'harness-eval-sealed-shard.NoId0000'), emptyId = join(f.tmp, 'harness-eval-sealed-shard.Empt0000'), numId = join(f.tmp, 'harness-eval-sealed-shard.Numb0000');
    for (const [d, receipt] of [[noId, {}], [emptyId, { run_id: '' }], [numId, { run_id: 7 }]] as const) { mkdirSync(join(d, 'root'), { recursive: true }); writeFileSync(join(d, 'root', 'opening-receipt.json'), JSON.stringify(receipt)); }
    writeFileSync(join(resultsA, 'shard-3', 'sealed-root-copy.path'), `${decoy}\n${otherRun}\n${partial}\n${unbound}\n${noId}\n${emptyId}\n${numId}\n`);
    const lines: string[] = [];
    const cleaned = cleanup({ repo: f.repo, exportJson: join(outA, 'export.json'), sealedRoot: rootA(), results: [resultsA], custody, log: (l) => lines.push(l) });
    expect(cleaned.removed).toEqual([rootA(), resultsA, shardCopy, partial]);
    expect(cleaned.unresolvedCopies).toEqual([unbound, noId, emptyId, numId]);
    expect([existsSync(rootA()), existsSync(resultsA), existsSync(shardCopy), existsSync(partial), existsSync(decoy), existsSync(otherRun), existsSync(unbound), existsSync(noId), existsSync(emptyId), existsSync(numId)]).toEqual([false, false, false, false, true, true, true, true, true, true]);
    expect(lines[0]).toContain(`and 2 sealed shard copies of the root a killed shard left (${shardCopy}, ${partial})`);
    expect(lines.some((l) => l.includes(`unresolved sealed shard copies: ${unbound}, ${noId}, ${emptyId}, ${numId}`))).toBe(true);
  }, 60_000);

  // Value: protects=export makes every claim source again from trials.jsonl, so a stale superiority-only comparisons.json is
  //   overwritten and never decides a claim, and it refuses, pushing and publishing nothing, a manifest recipient that is not
  //   sealed/recipient.txt, a receipt whose access.event_sha256 is not the run's "opened" line, a receipt with an
  //   empty access block or none while the run has no "opened" line, and a set with a "released" line, whether that line was
  //   there before the export or landed after it read the log; fails_when=export reads a comparisons file already in the raw
  //   results, takes a missing digest and a missing line as equal, or drops one of the refusals or the recheck inside the
  //   push transaction; why_new=the other export tests never plant a comparisons file, another recipient, a forged or
  //   stripped receipt or a released line;
  //   seam=a now() hook that pushes a released line once the export has passed its last read before the push;
  //   no_claim=gbrain claim sources (comparisons.gbrain.json takes the same path); fixture repo and custody remote are local
  test('export regenerates a stale claim source and refuses another recipient, an unadmitted receipt and a released set', async () => {
    const D: RunSpec = { runId: 'syn-dev-3', dir: '2026-11-24-syn-dev-3', label: 'dev', reason: 'synthetic third dev opening', candidate: candidate('dev-3') };
    register(f, D);
    const preregFile = join(f.repo, preregOf(D));
    const prereg = JSON.parse(readFileSync(preregFile, 'utf8')) as { heldout: { claims: Array<{ rule: string }> } };
    prereg.heldout.claims = prereg.heldout.claims.filter((c) => c.rule === 'superiority');
    writeFileSync(preregFile, JSON.stringify(prereg, null, 2) + '\n');
    commitPush(f, 'syn-dev-3 decides its superiority claim only');
    const preOpenD = git(f.bare, 'rev-parse', 'refs/heads/custody');
    const rootD = (await openRun({ repo: f.repo, prereg: preregOf(D), ...co(f), out: join(f.work, 'root-dev-3'), log: () => undefined })).root;
    const resultsD = join(f.work, 'results', D.runId), receiptD = join(rootD, 'opening-receipt.json'), outD = sealedResultsOf(f, D);
    const flags = ['--sealed-root', rootD, '--opening-receipt', receiptD];
    const bun = (args: string[]) => spawnSync(process.execPath, args, { cwd: f.repo, encoding: 'utf8', env: { PATH: process.env.PATH, HOME: process.env.HOME } });
    expect(bun([join(ROOT, 'runner', 'run.ts'), 'plan', '--prereg', preregOf(D), '--out', resultsD, ...flags]).status).toBe(0);
    expect(bun([join(ROOT, 'runner', 'run.ts'), 'run', '--manifest', join(resultsD, 'manifest.json'), '--harness-mode', 'scripted', ...flags]).status).toBe(0);
    let n = 0;
    const optsD = (o: Partial<ExportOptions> = {}): ExportOptions => ({ repo: f.repo, results: resultsD, sealedRoot: rootD, receipt: receiptD, custody: cloneCustody(f, `custody-export-d-${++n}`), gh: f.gh, log: () => undefined, ...o });
    const refusedD = (o: Partial<ExportOptions> = {}) => exportRun(optsD(o)).then(() => 'no refusal', (e: Error) => e.message);
    const exportedD = () => readAccessLog(cloneCustody(f, `check-d-${++n}`)).filter((e) => e.event === 'exported' && e.run_id === D.runId).length;

    // sealed/recipient.txt names another key than the one the set was sealed to
    const recipientFile = join(f.repo, 'sealed', 'recipient.txt'), recipientBytes = readFileSync(recipientFile);
    writeFileSync(recipientFile, (await identityToRecipient(await generateX25519Identity())) + '\n');
    expect(await refusedD()).toMatch(/^HE-SEALED-007 set vsyn is sealed to age1\S{12}\.\.\., but sealed\/recipient\.txt holds age1\S{12}\.\.\.; .*nothing was written or pushed$/);
    writeFileSync(recipientFile, recipientBytes);

    // a receipt, and the manifest's copy of it, naming an access event that is not the run's "opened" line
    const manifestFile = join(resultsD, 'manifest.json'), manifestBytes = readFileSync(manifestFile);
    const forge = <T extends { access: Record<string, unknown> }>(r: T): T => ({ ...r, access: { ...r.access, event_sha256: sha256('not the opened line') } });
    const forged = join(f.tmp, 'forged-receipt-d.json');
    writeFileSync(forged, JSON.stringify(forge(JSON.parse(readFileSync(receiptD, 'utf8'))), null, 1));
    const m = JSON.parse(manifestBytes.toString('utf8'));
    writeFileSync(manifestFile, JSON.stringify({ ...m, sealed: { ...m.sealed, receipt: forge(m.sealed.receipt) } }, null, 1));
    expect(await refusedD({ receipt: forged })).toMatch(/^HE-SEALED-007 the opening receipt's access\.event_sha256 \([0-9a-f]{12}\) is not the digest of run syn-dev-3's "opened" line in the access log on refs\/heads\/custody \([0-9a-f]{12}\); .*Nothing was pushed or published$/);

    // a receipt, and the manifest's copy of it, with an empty access block or none, while the custody branch has no "opened"
    // line for the run: the two missing digests are refused, never taken as equal
    const openedHead = git(f.bare, 'rev-parse', 'refs/heads/custody');
    git(f.bare, 'update-ref', 'refs/heads/custody', preOpenD);
    const strips: Array<(r: Record<string, unknown>) => Record<string, unknown>> = [(r) => ({ ...r, access: {} }), ({ access: _a, ...r }) => r];
    for (const strip of strips) {
      writeFileSync(forged, JSON.stringify(strip(JSON.parse(readFileSync(receiptD, 'utf8'))), null, 1));
      writeFileSync(manifestFile, JSON.stringify({ ...m, sealed: { ...m.sealed, receipt: strip(m.sealed.receipt) } }, null, 1));
      expect(await refusedD({ receipt: forged })).toMatch(/^HE-SEALED-007 the opening receipt's access\.event_sha256 \(none\) is not the digest of run syn-dev-3's "opened" line in the access log on refs\/heads\/custody \(no such line\); .*Nothing was pushed or published$/);
      expect(git(f.bare, 'rev-parse', 'refs/heads/custody')).toBe(preOpenD);
    }
    git(f.bare, 'update-ref', 'refs/heads/custody', openedHead);
    writeFileSync(manifestFile, manifestBytes);

    // a "released" line for the set, already in the log, then landing after the export's last read before the push
    const custodyHead = git(f.bare, 'rev-parse', 'refs/heads/custody');
    const plantReleased = () => {
      const c = cloneCustody(f, `custody-plant-released-${++n}`);
      writeFileSync(join(c, 'access-log.jsonl'), readFileSync(join(c, 'access-log.jsonl'), 'utf8') + JSON.stringify({ schema_version: 1, event: 'released', at: '2026-11-24T00:00:00Z', run_id: '*', set: SET, custodian: 'tests/sealed-coverage.test.ts' }) + '\n');
      git(c, 'commit', '-q', '-am', 'a released line');
      git(c, 'push', '-q', 'origin', 'HEAD:refs/heads/custody');
    };
    plantReleased();
    expect(await refusedD()).toMatch(/^HE-SEALED-007 set vsyn has a "released" line in the access log on refs\/heads\/custody; .*Nothing was pushed or published$/);
    git(f.bare, 'update-ref', 'refs/heads/custody', custodyHead);
    let planted = false;
    expect(await refusedD({ now: () => { if (!planted) { planted = true; plantReleased(); } return '2026-11-24T00:00:00.000Z'; } })).toMatch(/^HE-SEALED-007 set vsyn has a "released" line/);
    expect(planted).toBe(true);
    git(f.bare, 'update-ref', 'refs/heads/custody', custodyHead);
    expect([exportedD(), existsSync(join(outD, 'export.json'))]).toEqual([0, false]);

    // a stale comparisons.json whose base-to-cand entry would accept C1: export makes the file again and decides from it
    writeFileSync(join(resultsD, 'comparisons.json'), JSON.stringify({ scope: 'stale', grading: 'as recorded', seed: 1, draws: 10, comparisons: [{ a: 'base', b: 'cand', delta: 0.5, ci95: [0.3, 0.7], p: 0.0001, holm_p: 0.0001 }] }));
    const d = await exportRun(optsD());
    expect((d.export.decisions as Array<{ claim: string; decision: string }>).map((x) => [x.claim, x.decision])).toEqual([['C1', 'reject']]);
    const remade = JSON.parse(readFileSync(join(resultsD, 'comparisons.json'), 'utf8')) as { scope: unknown; comparisons: Array<{ a?: string; b?: string; delta: number }> };
    expect([remade.scope === 'stale', remade.comparisons.find((c) => c.a === 'base' && c.b === 'cand')?.delta === 0.5]).toEqual([false, false]);
    expect([exportedD(), readdirSync(outD).sort()]).toEqual([1, ['README.md', 'export.json', 'opening-receipt.json']]);
  }, 120_000);
});

describe('summarize-run with a missing task tree (HE-TASK-005)', () => {
  const RUN = 'missing-task-fixture-2026-11';
  const trial = (task: string, rep: number): TrialRecord => ({
    trial_id: `${RUN}/a-dev/${task}/r${rep}`, cell: 'a-dev', task, harness: 'a', harness_mode: 'docker', model: 'm1', script: null,
    termination: 'completed', grade: 'pass', consent_violation: false, approval_stop: false, effects: [],
    predicates: [{ id: 'answer', kind: 'required', passed: true, evidence: 'matched' }], cap_stop: false, turns: { planned: 2, run: 2, exits: [0, 0] },
    usage: { meter_id: 'k', requests: 1, refused: 0, failed: 0, usd: 0.01, input_tokens: 10, output_tokens: 10, cached_tokens: 0, unpriced: 0, by_model: {}, upstream: null },
    wall_ms: 1000, started_at: '', ended_at: '', paths: {},
  } as TrialRecord);

  // Value: protects=a plaintext run whose task.toml is missing keeps the old family "unknown" fallback with one WARN line
  //   (HE-TASK-005) and lists the task under families_unresolved, with and without --allow-missing-tasks; fails_when=the
  //   sealed-only refusal reaches a plaintext v0.1/v0.2 run, or the task stops being listed; why_new=every summarize-run
  //   fixture has all its tasks present; seam=none; no_claim=the sealed refusal (sealed-e2e covers HE-SEALED-001);
  //   hand-built trial records, no harness run
  test('a plaintext trial whose task tree is missing is counted as family unknown with a warning and recorded, with or without --allow-missing-tasks', () => {
    const dir = mkdtempSync(join(tmpdir(), 'he-missing-task-'));
    tmps.push(dir);
    const present = 'si-01-quarrendon-seats', missing = 'zz-99-no-such-task';
    const missingDir = join(ROOT, 'tasks', 'multiuser', 'dev', missing);
    expect(existsSync(join(ROOT, 'tasks', 'multiuser', 'dev', present, 'task.toml'))).toBe(true);
    writeFileSync(join(dir, 'manifest.json'), JSON.stringify({ schema_version: 1, run_id: RUN, cells: [{ id: 'a-dev', harness: 'a', model: 'm1', slice: 'multiuser', split: 'dev', repetitions: 2 }], trials: [] }));
    writeFileSync(join(dir, 'trials.jsonl'), [trial(present, 1), trial(present, 2), trial(missing, 1), trial(missing, 2)].map((t) => JSON.stringify(t)).join('\n') + '\n');
    const run = (extra: string[]) => spawnSync(process.execPath, [join(ROOT, 'scripts', 'summarize-run.ts'), '--results', dir, ...extra], { cwd: ROOT, encoding: 'utf8' });

    // a plaintext run keeps its old fallback (family "unknown") with one WARN line; only a sealed run refuses
    const plain = run([]);
    expect(plain.status).toBe(0);
    expect(plain.stderr).toContain('WARN: HE-TASK-005 1 task(s) counted under family "unknown"; summary.json lists them under families_unresolved');
    expect(plain.stderr).not.toContain(present);
    const plainSummary = JSON.parse(readFileSync(join(dir, 'summary.json'), 'utf8')) as { families_unresolved?: string[] };
    expect(plainSummary.families_unresolved).toEqual([`${missing} (cell a-dev, looked in ${missingDir})`]);
    rmSync(join(dir, 'summary.json'));

    const allowed = run(['--allow-missing-tasks']);
    expect(allowed.status).toBe(0);
    expect(allowed.stderr).toContain('WARN: HE-TASK-005 1 task(s) counted under family "unknown" (--allow-missing-tasks)');
    const summary = JSON.parse(readFileSync(join(dir, 'summary.json'), 'utf8')) as { families_unresolved?: string[] };
    expect(summary.families_unresolved).toEqual([`${missing} (cell a-dev, looked in ${missingDir})`]);
  }, 60_000);
});

// Issue #192: a Claude Code or Codex installer view holds the compiled gbrain its hook runs (207 MB, about 67 MiB gzipped). The view's
// manifest.json records its sha256 and the image holds it, so the raw results bundle leaves it out; two copies (a merged sharded run
// keeps one per shard plus gbrain-install/) would put the bundle over the 95 MiB one pushed file may hold.
test('rawEntries leaves out the installer views\' gbrain binary, in gbrain-install/ and in every <shard>.gbrain-install/, and keeps the rest of each view', () => {
  const raw = mkdtempSync(join(tmpdir(), 'he-raw-'));
  tmps.push(raw);
  const put = (rel: string, data = 'x') => { mkdirSync(join(raw, rel, '..'), { recursive: true }); writeFileSync(join(raw, rel), data); };
  const manifest = (h: string, bin: string, digestOf = bin, binSource = `${h}/installer/home/.local/bin/gbrain`) => {
    const files = [{ path: 'home/.local/bin/gbrain', source_path: binSource, sha256: sha256(bin) }, { path: 'home/claude/CLAUDE.md', source_path: `${h}/installer/home/claude/CLAUDE.md`, sha256: sha256('x') }];
    const lines = [{ s: binSource, d: sha256(digestOf) }, { s: `${h}/installer/home/claude/CLAUDE.md`, d: sha256('x') }].sort((a, b) => (a.s < b.s ? -1 : 1)).map((l) => `${l.s} ${l.d}\n`).join('');
    return JSON.stringify({ view_digest: sha256(lines), files });
  };
  const record = (harness: string, bin: string) => JSON.stringify({ gbrain: { install_bundle: { harness, split: 'heldout', install: 'gbrain-installer', files: 2, view_digest: (JSON.parse(manifest(harness, bin)) as { view_digest: string }).view_digest } } });
  const codex = 's2.gbrain-install/codex-installer/heldout';
  for (const view of ['gbrain-install/claude-code-installer/heldout', 's1.gbrain-install/claude-code-installer/heldout', codex]) {
    const h = view.includes('codex') ? 'codex' : 'claude-code';
    put(view + '/home/.local/bin/gbrain', 'ELF');
    put(view + '/home/claude/CLAUDE.md');
    put(view + '/manifest.json', manifest(h, 'ELF'));
  }
  put('gbrain-install/hermes-installer/heldout/home/.hermes/SOUL.md');
  put('trials.jsonl', `{}\n${record('claude-code', 'ELF')}\n${record('codex', 'ELF')}\n`);
  put('notes/home/.local/bin/gbrain');
  const paths = rawEntries(raw).map((e) => e.path).sort();
  expect(paths.filter((p) => p.endsWith('/home/.local/bin/gbrain'))).toEqual(['notes/home/.local/bin/gbrain']);
  expect(paths).toContain('gbrain-install/claude-code-installer/heldout/manifest.json');
  expect(paths).toContain(codex + '/home/claude/CLAUDE.md');
  expect(paths).toContain('gbrain-install/hermes-installer/heldout/home/.hermes/SOUL.md');
  expect(paths).toContain('trials.jsonl');
  const refused = /HE-SEALED-007 s2\.gbrain-install\/codex-installer\/heldout\/home\/\.local\/bin\/gbrain is not the binary its view's manifest\.json records \(no entry with source_path codex\/installer\/home\/\.local\/bin\/gbrain, another sha256, or a view_digest that is not the digest of the manifest's file list\)/;
  // A binary its manifest does not vouch for is refused, never left out unchecked.
  put(codex + '/home/.local/bin/gbrain', 'ELF2');
  expect(() => rawEntries(raw)).toThrow(refused);
  // A manifest rewritten to list the swapped binary, with a view_digest that is no longer the digest of its file list, is refused too.
  put(codex + '/manifest.json', manifest('codex', 'ELF2', 'ELF'));
  expect(() => rawEntries(raw)).toThrow(refused);
  // An entry whose path says home/.local/bin/gbrain but whose source_path (the part view_digest covers) names another file is refused.
  put(codex + '/manifest.json', manifest('codex', 'ELF2', 'ELF2', 'codex/installer/home/claude/OTHER'));
  expect(() => rawEntries(raw)).toThrow(refused);
  // A consistent view whose view_digest no trial recorded for codex heldout keeps its binary in the bundle; once a trial records it,
  // the binary is left out.
  put(codex + '/manifest.json', manifest('codex', 'ELF2'));
  expect(rawEntries(raw).map((e) => e.path)).toContain(codex + '/home/.local/bin/gbrain');
  put('trials.jsonl', `${record('claude-code', 'ELF')}\n${record('codex', 'ELF')}\n${record('claude-code', 'ELF2')}\n`);
  expect(rawEntries(raw).map((e) => e.path)).toContain(codex + '/home/.local/bin/gbrain');
  put('trials.jsonl', `${record('claude-code', 'ELF')}\n${record('codex', 'ELF2')}\n`);
  expect(rawEntries(raw).map((e) => e.path)).not.toContain(codex + '/home/.local/bin/gbrain');
  // Only Claude Code and Codex installer views leave their binary out; any other view keeps every file.
  put('gbrain-install/openclaw-installer/heldout/home/.local/bin/gbrain', 'ELF');
  expect(rawEntries(raw).map((e) => e.path)).toContain('gbrain-install/openclaw-installer/heldout/home/.local/bin/gbrain');
  put(codex + '/home/.local/bin/gbrain', 'ELF');
  put(codex + '/manifest.json', '{}');
  expect(() => rawEntries(raw)).toThrow(/HE-SEALED-007/);
});

